package com.therighthon.rnr.common.blockentity;
import com.therighthon.rnr.common.RNRBlockEntities; import net.minecraft.core.BlockPos; import net.minecraft.nbt.CompoundTag; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.entity.BlockEntity; import net.minecraft.world.level.block.state.BlockState;
public class RNRTickCounterBlockEntity extends BlockEntity { private long lastUpdateTick; public RNRTickCounterBlockEntity(BlockPos p,BlockState s){super(RNRBlockEntities.TICK_COUNTER.get(),p,s);} public long getLastUpdateTick(){return lastUpdateTick;} public void setLastUpdateTick(long t){lastUpdateTick=t;setChanged();} public long getTicksSinceUpdate(){return level==null?0:Math.max(0,level.getGameTime()-lastUpdateTick);} public static void reset(Level l,BlockPos p){if(l.getBlockEntity(p) instanceof RNRTickCounterBlockEntity e)e.setLastUpdateTick(l.getGameTime());} protected void saveAdditional(CompoundTag t){super.saveAdditional(t);t.putLong("LastUpdateTick",lastUpdateTick);} public void load(CompoundTag t){super.load(t);lastUpdateTick=t.getLong("LastUpdateTick");} }
